//! Differential fuzz test for `text_decoder.rs` against ground truth
//! generated by running Node's `TextDecoder` (streaming mode) — see
//! PARITY.md. Corpus: `tests/data/decoder-fuzz.json`; skipped when absent.

use pi_core::text_decoder::StreamingDecoder;
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    /// Byte chunks, each hex-encoded.
    chunks: Vec<String>,
    /// Expected concatenated output.
    out: String,
}

#[test]
fn decoder_fuzz_ground_truth() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/decoder-fuzz.json");
    let Ok(data) = std::fs::read_to_string(path) else {
        eprintln!("skipping: {} not found", path);
        return;
    };
    let cases: Vec<Case> = serde_json::from_str(&data).expect("valid corpus");
    assert!(cases.len() > 500, "corpus too small");
    let mut mismatches = 0;
    for (i, case) in cases.iter().enumerate() {
        let mut decoder = StreamingDecoder::new();
        let mut out = String::new();
        for chunk in &case.chunks {
            let bytes = hex_decode(chunk);
            out.push_str(&decoder.decode(&bytes));
        }
        out.push_str(&decoder.finish());
        if out != case.out {
            mismatches += 1;
            if mismatches <= 5 {
                eprintln!("case {}: chunks={:?} got={:?} want={:?}", i, case.chunks, out, case.out);
            }
        }
    }
    assert_eq!(mismatches, 0, "{} mismatches", mismatches);
}

fn hex_decode(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex byte"))
        .collect()
}
